alter table public.holds add column if not exists item_id uuid;
alter table public.holds add column if not exists patron_id uuid;
alter table public.holds add column if not exists note text;
alter table public.holds add column if not exists state text default 'placed'::text;

-- entity_spec から導出される CHECK。同じ式なら置き換えても差分にならない。
do $$
begin
    if not exists (
        select 1 from pg_constraint c
        where c.conrelid = 'public.holds'::regclass and c.conname = 'holds_note_max_length'
          and pg_get_constraintdef(c.oid) = 'CHECK ((char_length(note) <= 200))'
    ) then
        alter table public.holds drop constraint if exists holds_note_max_length;
        alter table public.holds add constraint holds_note_max_length check (char_length(note) <= 200);
    end if;
end
$$;
do $$
begin
    if not exists (
        select 1 from pg_constraint c
        where c.conrelid = 'public.holds'::regclass and c.conname = 'holds_state_enum'
          and pg_get_constraintdef(c.oid) = 'CHECK ((state = ANY (ARRAY[''placed''::text, ''ready''::text, ''collected''::text, ''cancelled''::text])))'
    ) then
        alter table public.holds drop constraint if exists holds_state_enum;
        alter table public.holds add constraint holds_state_enum check (state = ANY (ARRAY['placed'::text, 'ready'::text, 'collected'::text, 'cancelled'::text]));
    end if;
end
$$;

-- 外部キー。**両側の表のファイルに出す** —— 両方の表が在って、その列にまだ外部キーが無いときだけ張るので、先に当たった側は通り過ぎ、後から当たった側で張られる(相互参照する 2 表でも当たる)。既にある(名前が違っていても同じ列の)ものには触れない。
do $$
begin
    if to_regclass('public.holds') is not null and to_regclass('public.items') is not null then
        if not exists (
            select 1 from pg_constraint c
            where c.conrelid = 'public.holds'::regclass and c.contype = 'f'
              and pg_get_constraintdef(c.oid) like 'FOREIGN KEY (item_id)%'
        ) then
            alter table public.holds add constraint holds_item_id_fkey
                foreign key (item_id) references public.items (id) on delete no action;
        end if;
    end if;
end
$$;
do $$
begin
    if to_regclass('public.holds') is not null and to_regclass('public.patrons') is not null then
        if not exists (
            select 1 from pg_constraint c
            where c.conrelid = 'public.holds'::regclass and c.contype = 'f'
              and pg_get_constraintdef(c.oid) like 'FOREIGN KEY (patron_id)%'
        ) then
            alter table public.holds add constraint holds_patron_id_fkey
                foreign key (patron_id) references public.patrons (id) on delete no action;
        end if;
    end if;
end
$$;

-- 索引(主キーの裏は除く)。
do $$
begin
    if to_regclass('public.holds_active_unique') is not null then
        create temp table declared_index_probe (like public.holds) on commit drop;
        create unique index declared_index_probe_idx on pg_temp.declared_index_probe (item_id, patron_id) where ((state <> ALL (ARRAY['collected'::text, 'cancelled'::text])));
        if split_part(pg_get_indexdef('pg_temp.declared_index_probe_idx'::regclass), ' USING ', 2) <> split_part(pg_get_indexdef('public.holds_active_unique'::regclass), ' USING ', 2)
            or (select indisunique from pg_index where indexrelid = 'pg_temp.declared_index_probe_idx'::regclass) <> (select indisunique from pg_index where indexrelid = 'public.holds_active_unique'::regclass) then
            drop index public.holds_active_unique;
        end if;
        drop table pg_temp.declared_index_probe;
    end if;
end;
$$;
create unique index if not exists holds_active_unique on public.holds (item_id, patron_id) where ((state <> ALL (ARRAY['collected'::text, 'cancelled'::text])));
create index if not exists holds_patron_id_state_id_idx on public.holds (patron_id, state, id);
create index if not exists holds_state_id_idx on public.holds (state, id);

